import csv
import io
import re


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    original_limit = csv.field_size_limit()
    required_limit = max(original_limit, len(raw_csv) + 1)

    try:
        try:
            csv.field_size_limit(required_limit)
        except (OverflowError, ValueError):
            csv.field_size_limit(2147483647)

        expected_names = {
            "date",
            "time",
            "qty",
            "productid",
            "price",
            "producttype",
            "productdescription",
            "url",
            "comments",
        }

        def read_rows(text):
            return list(csv.reader(
                io.StringIO(text, newline=""),
                delimiter=",",
                quotechar='"',
                doublequote=True,
                skipinitialspace=False,
                strict=False,
            ))

        def normalized_name(value):
            return re.sub(r"[^a-z0-9]+", "", value.lstrip("\ufeff").lower())

        def header_score(row):
            if not row:
                return 0
            return sum(
                1 for value in row
                if normalized_name(value) in expected_names
            )

        start_offset = None
        offset = 0

        for physical_line in raw_csv.splitlines(keepends=True):
            try:
                candidate_rows = read_rows(physical_line)
            except csv.Error:
                candidate_rows = []

            if candidate_rows:
                candidate = candidate_rows[0]
                if len(candidate) == 9 and header_score(candidate) >= 5:
                    start_offset = offset
                    break

            offset += len(physical_line)

        source = raw_csv[start_offset:] if start_offset is not None else raw_csv

        try:
            parsed = read_rows(source)
        except csv.Error:
            parsed = []
            for line in source.splitlines():
                try:
                    parsed.extend(read_rows(line))
                except csv.Error:
                    parsed.append(line.split(","))

        header_index = None
        best_score = -1

        for index, row in enumerate(parsed):
            score = header_score(row)
            if score > best_score:
                best_score = score
                header_index = index
            if len(row) == 9 and score >= 5:
                header_index = index
                break

        if header_index is None or not parsed:
            return {"columns": [], "rows": []}

        if best_score < 2:
            for index, row in enumerate(parsed):
                if row:
                    header_index = index
                    break

        header = list(parsed[header_index])
        if header:
            header[0] = header[0].lstrip("\ufeff")

        width = 9

        if len(header) < width:
            header.extend("" for _ in range(width - len(header)))
        elif len(header) > width:
            header = header[:width - 1] + [",".join(header[width - 1:])]

        def normalize_row(row):
            values = list(row)

            if len(values) == width:
                return values

            url_index = None
            for index, value in enumerate(values):
                if re.match(r"^\s*(?:https?|ftp)://", value, re.IGNORECASE):
                    url_index = index
                    break

            if url_index is not None and url_index >= 5:
                if url_index < 7:
                    values[url_index:url_index] = [""] * (7 - url_index)
                    url_index = 7

                if url_index > 7:
                    middle = values[5:url_index]
                    if len(middle) >= 2:
                        product_type = ",".join(middle[:-1])
                        description = middle[-1]
                    elif middle:
                        product_type = middle[0]
                        description = ""
                    else:
                        product_type = ""
                        description = ""

                    comments = ",".join(values[url_index + 1:])
                    values = (
                        values[:5]
                        + [product_type, description, values[url_index], comments]
                    )

            if len(values) > width:
                if len(values) >= 8:
                    values = (
                        values[:5]
                        + [",".join(values[5:len(values) - 3])]
                        + values[len(values) - 3:]
                    )
                else:
                    values = values[:width - 1] + [
                        ",".join(values[width - 1:])
                    ]

            if len(values) < width:
                values.extend("" for _ in range(width - len(values)))

            return values

        rows = []
        for row in parsed[header_index + 1:]:
            if not row:
                continue
            rows.append(normalize_row(row))

        return {"columns": header, "rows": rows}
    finally:
        try:
            csv.field_size_limit(original_limit)
        except (OverflowError, ValueError):
            pass
